$ErrorActionPreference='Continue'
$repo='C:\Users\Xxkan\mhw-mods-work-canonical'
Set-Location $repo
git fetch origin --prune
if($LASTEXITCODE -ne 0){ throw 'fetch failed' }
$active=@()
foreach($line in @(git worktree list --porcelain)){ if($line -like 'branch refs/heads/*'){ $active += $line.Substring(18) } }
$remote=@(git for-each-ref --format='%(refname:strip=3)' refs/remotes/origin | Where-Object { $_ -and $_ -ne 'HEAD' -and $_ -ne 'main' -and $_ -ne 'heaven-bridge' })
$deleted=@(); $preserved=@()
foreach($b in $remote){
  if($b -in $active){ $preserved += [ordered]@{branch=$b;reason='active-worktree'}; continue }
  git merge-base --is-ancestor "origin/$b" origin/main
  if($LASTEXITCODE -eq 0){
    git push origin --delete $b
    if($LASTEXITCODE -eq 0){$deleted += [ordered]@{branch=$b;proof='ancestor-of-main'}} else {$preserved += [ordered]@{branch=$b;reason='delete-failed'}}
    continue
  }
  $cherry=@(git cherry origin/main "origin/$b" 2>$null)
  $plus=@($cherry | Where-Object { $_ -like '+ *' })
  if($plus.Count -eq 0){
    git push origin --delete $b
    if($LASTEXITCODE -eq 0){$deleted += [ordered]@{branch=$b;proof='patch-equivalent-to-main'}} else {$preserved += [ordered]@{branch=$b;reason='delete-failed'}}
  } else {
    $preserved += [ordered]@{branch=$b;reason='unique-patches';unique=$plus.Count}
  }
}
git fetch origin --prune | Out-Null
$remaining=@(git for-each-ref --format='%(refname:strip=3)' refs/remotes/origin | Where-Object { $_ -and $_ -ne 'HEAD' -and $_ -ne 'main' })
[ordered]@{main=(git rev-parse origin/main);deleted=$deleted;preserved=$preserved;active_worktrees=$active;remaining_remote_count=$remaining.Count;remaining_remote=$remaining} | ConvertTo-Json -Depth 6
